#!/usr/bin/env bash
# 升级脚本 v5：全标的监控 / 自动加标的 / rank / 执行模式切换（保留 v3 仪表盘与 v4 风控）
# 用法（在仓库根目录运行）：
#   bash upgrade_v5.sh            # 升级 + 测试 + 本地 git commit
#   bash upgrade_v5.sh --push     # 另外 git push
#   bash upgrade_v5.sh --no-commit
# 不会改动：.env、data/、logs/、.venv/。
# 旧 config/config.yaml 备份为 config/config.yaml.bak-<时间>；旧 arb/ tests/ 移到 .upgrade_backup/<时间>/。
set -euo pipefail
PUSH=0; COMMIT=1
for a in "$@"; do
  case "${a}" in
    --push) PUSH=1 ;;
    --no-commit) COMMIT=0 ;;
    *) echo "未知参数: ${a}"; exit 2 ;;
  esac
done
if [ ! -d arb ] || [ ! -f requirements.txt ]; then
  echo "错误：请在 lighter-robinhood-entropyIO-trading 仓库根目录运行（找不到 arb/ 或 requirements.txt）"; exit 1
fi
TS=$(date +%Y%m%d-%H%M%S)
TMP=$(mktemp -d)
echo "==> 解压新版本"
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xzf - -C "${TMP}"
if [ -f config/config.yaml ]; then
  cp config/config.yaml "config/config.yaml.bak-${TS}"
  echo "==> 已备份旧配置: config/config.yaml.bak-${TS}（如有自定义参数请手动合并到新 config.yaml）"
fi
BK=".upgrade_backup/${TS}"
mkdir -p "${BK}"
for d in arb tests; do [ -e "${d}" ] && mv "${d}" "${BK}/"; done
echo "==> 旧代码已移到 ${BK}/，安装新代码"
cp -a "${TMP}"/. .
chmod +x start.sh 2>/dev/null || true

for pat in '.upgrade_backup/' 'config/config.yaml.bak-*'; do
  grep -qxF "${pat}" .gitignore 2>/dev/null || echo "${pat}" >> .gitignore
done

PY=python3
if [ -x .venv/bin/python ]; then PY=.venv/bin/python; fi
echo "==> 安装依赖（${PY}）"
${PY} -m pip install -q -r requirements-dev.txt || echo "警告：依赖安装失败，请手动执行 pip install -r requirements-dev.txt"
echo "==> 运行测试"
${PY} -m pytest -q tests
echo "==> 离线配置检查"
${PY} -m arb check || echo "警告：arb check 未通过（可能是 .env 未填写），请查看上面的输出"

if [ "${COMMIT}" = 1 ] && [ -d .git ]; then
  git add -A
  if git diff --cached --quiet; then
    echo "==> 没有变更需要提交"
  else
    git commit -q -m "v5: 自动加标的、rank 打分、taker->taker 开仓、命令行切换 maker/模式、仪表盘排序" && echo "==> 已提交" || echo "警告：git commit 失败（检查 git user.name/email），代码已升级，可手动提交"
  fi
  if [ "${PUSH}" = 1 ]; then git push && echo "==> 已推送"; fi
fi
echo "==> 升级完成（v5）。新功能见 README「v5」一节和 config.yaml 的 auto_symbols: / ui: 段；运行 ./start.sh monitor 查看仪表盘，./start.sh rank 查看打分。确认无误后可删除 ${BK}"
exit 0
